  //===========================================================================
  // AXI-LITE COMPARISON
  //===========================================================================
  function void compare_axi_lite();
    sd_emmc_controller_axi_lite_agent_seq_item actual_tr;
    sd_emmc_controller_axi_lite_agent_seq_item expected_tr;
    if (axi_lite_actual_q.size() == 0)
      return;
    if (axi_lite_expected_q.size() == 0)
      return;
    actual_tr   = axi_lite_actual_q.pop_front();
    expected_tr = axi_lite_expected_q.pop_front();
   
    if (mask_status_reads && actual_tr.cmd == sd_emmc_controller_axi_lite_agent_seq_item::AXI_READ && actual_tr.addr == 32'h24)
  expected_tr.read_data[2:0] = actual_tr.read_data[2:0];
    if (actual_tr.compare(expected_tr)) begin
      axi_lite_match_count++;
      //`uvm_info("SB_AXI_LITE_MATCH", "AXI-Lite transaction match", UVM_MEDIUM)
      `uvm_info("SB_AXI_LITE_MATCH", 
        $sformatf("\n[MATCH] AXI-Lite Transaction Matched!\n--- EXPECTED ---\n%s\n--- ACTUAL ---\n%s", 
                  expected_tr.convert2string(), actual_tr.convert2string()), UVM_LOW)
    end
    else begin
      axi_lite_mismatch_count++;
      //`uvm_error("SB_AXI_LITE_MISMATCH", $sformatf("\nAXI-Lite transaction mismatch\n\nEXPECTED:\n%s\nACTUAL:\n%s", expected_tr.sprint(), actual_tr.sprint()))
      // Goal: when a status-register read still mismatches, show why the
	// mask in compare_axi_lite did not neutralize it (flag off vs. cmd name).
	`uvm_error("SB_AXI_LITE_MISMATCH", 
 	 $sformatf("\n[MISMATCH] AXI-Lite Transaction Mismatch! (mask_status_reads=%0b cmd.name=\"%s\")\n--- EXPECTED ---\n%s\n--- ACTUAL ---\n%s", 
            mask_status_reads, actual_tr.cmd.name(),
            expected_tr.convert2string(), actual_tr.convert2string()))
    end
  endfunction

  //===========================================================================
  // AXI-MEM COMPARISON
  //===========================================================================
  function void compare_axi_mem();
    sd_emmc_controller_axi_mem_agent_seq_item actual_tr;
    sd_emmc_controller_axi_mem_agent_seq_item expected_tr;
    if (axi_mem_actual_q.size() == 0)
      return;
    if (axi_mem_expected_q.size() == 0)
      return;
    //--------------------------------------------------------------------------
    // Ordered comparison
    //--------------------------------------------------------------------------
    if (!axi_mem_allow_out_of_order) begin
      actual_tr   = axi_mem_actual_q.pop_front();
      expected_tr = axi_mem_expected_q.pop_front();
      if (actual_tr.compare(expected_tr)) begin
        axi_mem_match_count++;
       // `uvm_info("SB_AXI_MEM_MATCH", "AXI-MEM transaction MATCH", UVM_MEDIUM )
       `uvm_info("SB_AXI_MEM_MATCH", 
          $sformatf("\n[MATCH] AXI-MEM Transaction Matched!\n--- EXPECTED ---\n%s\n--- ACTUAL ---\n%s", 
                    expected_tr.convert2string(), actual_tr.convert2string()), UVM_LOW)
      end
      else begin
        axi_mem_mismatch_count++;
        `uvm_error("SB_AXI_MEM_MISMATCH", 
          $sformatf("\n[MISMATCH] AXI-MEM Transaction Mismatch!\n--- EXPECTED ---\n%s\n--- ACTUAL ---\n%s", 
                    expected_tr.convert2string(), actual_tr.convert2string()))
      end
    end
    else begin

      //--------------------------------------------------------------------------
      // Generic fallback for out-of-order mode.
      //
      // The current implementation searches for a transaction that compares
      // equal. This does not require knowledge of AXI fields.
      //
      // For production AXI systems with multiple outstanding transactions,
      // matching by AXI ID is recommended.
      //--------------------------------------------------------------------------
      int match_index = -1; 
      bit found = 1'b0;;
      actual_tr = axi_mem_actual_q.pop_front();
      //match_index = -1;
      //found       = 1'b0;
      foreach (axi_mem_expected_q[i]) begin
        if (actual_tr.compare(axi_mem_expected_q[i])) begin
          match_index = i;
          found       = 1'b1;
          break;
        end
      end

      if (found) begin
        expected_tr = axi_mem_expected_q[match_index];
        axi_mem_expected_q.delete(match_index);
        axi_mem_match_count++;
        //`uvm_info("SB_AXI_MEM_MATCH", "AXI-MEM out-of-order transaction MATCH", UVM_MEDIUM)
        `uvm_info("SB_AXI_MEM_MATCH", 
          $sformatf("\n[MATCH] AXI-MEM Out-of-Order Transaction Matched!\n--- EXPECTED ---\n%s\n--- ACTUAL ---\n%s", 
                    expected_tr.convert2string(), actual_tr.convert2string()), UVM_LOW)
      end
      else begin
        axi_mem_mismatch_count++;
       // `uvm_error("SB_AXI_MEM_MISMATCH", {"\nNo matching expected AXI-MEM transaction found", "\nACTUAL:\n", actual_tr.sprint() } )
        `uvm_error("SB_AXI_MEM_MISMATCH", 
          $sformatf("\n[MISMATCH] No matching expected AXI-MEM transaction found!\n--- ACTUAL ---\n%s", actual_tr.convert2string()))
      end
    end
  endfunction


