    end
    else begin
      sd_emmc_mismatch_count++;
  `uvm_error("SB_SD_EMMC_MISMATCH", 
        $sformatf("\n[MISMATCH] SD/eMMC Transaction Mismatch!\n--- EXPECTED ---\n%s\n--- ACTUAL ---\n%s", 
                  expected_tr.convert2string(), actual_tr.convert2string()))
      //`uvm_error("SB_SD_EMMC_MISMATCH", {"\nSD/eMMC transaction mismatch", "\nEXPECTED:\n", expected_tr.sprint(), "\nACTUAL:\n",actual_tr.sprint()})
    end
  endfunction

  //===========================================================================
  // END OF SIMULATION CHECK
  //===========================================================================
  function void check_phase(uvm_phase phase);
    super.check_phase(phase);
    //--------------------------------------------------------------------------
    // Perform remaining comparisons.
    //
    // This is useful when expected and actual transactions do not arrive
    // simultaneously.
    //--------------------------------------------------------------------------
    if (check_axi_lite) begin
      while ((axi_lite_actual_q.size() > 0) &&
             (axi_lite_expected_q.size() > 0)) begin
        compare_axi_lite();
      end
    end
    if (check_axi_mem) begin
      while ((axi_mem_actual_q.size() > 0) &&
             (axi_mem_expected_q.size() > 0)) begin
        compare_axi_mem();
      end
    end
    if (check_sd_emmc) begin
      while ((sd_emmc_actual_q.size() > 0) &&
             (sd_emmc_expected_q.size() > 0)) begin
        compare_sd_emmc();
      end
    end
    
    //--------------------------------------------------------------------------
    // Report unmatched AXI-Lite transactions.
    //--------------------------------------------------------------------------
    if (check_axi_lite && axi_lite_actual_q.size() != 0) begin
      `uvm_error("SB_AXI_LITE_UNMATCHED_ACTUAL", $sformatf("%0d AXI-Lite actual transaction(s) have no expected transaction", axi_lite_actual_q.size()))
    end
    if (check_axi_lite && axi_lite_expected_q.size() != 0) begin
      `uvm_error("SB_AXI_LITE_UNMATCHED_EXPECTED", $sformatf("%0d AXI-Lite expected transaction(s) were never observed", axi_lite_expected_q.size()))
    end
    
    //--------------------------------------------------------------------------
    // Report unmatched AXI-MEM transactions.
    //--------------------------------------------------------------------------
    if (axi_mem_actual_q.size() != 0) begin
      `uvm_error("SB_AXI_MEM_UNMATCHED_ACTUAL", $sformatf("%0d AXI-MEM actual transaction(s) have no expected transaction",axi_mem_actual_q.size()))
    end
    if (axi_mem_expected_q.size() != 0) begin
      `uvm_error("SB_AXI_MEM_UNMATCHED_EXPECTED", $sformatf("%0d AXI-MEM expected transaction(s) were never observed", axi_mem_expected_q.size()))
    end
    
    //--------------------------------------------------------------------------
    // Report unmatched SD/eMMC transactions.
    //--------------------------------------------------------------------------
    if (sd_emmc_actual_q.size() != 0) begin
      `uvm_error("SB_SD_EMMC_UNMATCHED_ACTUAL", $sformatf("%0d SD/eMMC actual transaction(s) have no expected transaction", sd_emmc_actual_q.size()))
    end
    if (sd_emmc_expected_q.size() != 0) begin
      `uvm_error("SB_SD_EMMC_UNMATCHED_EXPECTED", $sformatf("%0d SD/eMMC expected transaction(s) were never observed", sd_emmc_expected_q.size()))
    end
  endfunction

