   summary_str = $sformatf("\n============================================================\n              AXI-LITE SCOREBOARD SUMMARY\n============================================================\n  Actual      : %0d\n  Expected    : %0d\n  Matches     : %0d\n  Mismatches  : %0d\n============================================================", axi_lite_actual_count, axi_lite_expected_count, axi_lite_match_count, axi_lite_mismatch_count);
