    `uvm_info("SB_AXI_MEM_SUMMARY", summary_str, UVM_LOW)

    // SD/eMMC Summary
    summary_str = $sformatf("\n============================================================\n              SD/eMMC SCOREBOARD SUMMARY\n============================================================\n  Actual      : %0d\n  Expected    : %0d\n  Matches     : %0d\n  Mismatches  : %0d\n============================================================", sd_emmc_actual_count, sd_emmc_expected_count, sd_emmc_match_count, sd_emmc_mismatch_count);
    `uvm_info("SB_SD_EMMC_SUMMARY", summary_str, UVM_LOW)
    
   endfunction 
  
